package dev.lockra.mobile

import android.app.Activity
import android.content.Intent
import app.tauri.annotation.Command
import app.tauri.annotation.InvokeArg
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Invoke
import app.tauri.plugin.Plugin

@InvokeArg
class ScanArgs {
    var prompt: String = ""
    var cancel: String = ""
}

/**
 * The camera for the import (src/scanner.rs calls `scan` from Rust; the webview cannot): it opens
 * ScannerActivity, which answers the call itself with the first QR code it reads, or with how the
 * scan ended. Not generated by `cargo tauri android init`: keep this file when regenerating the
 * project.
 */
@TauriPlugin
class ScannerPlugin(private val activity: Activity) : Plugin(activity) {
    @Command
    fun scan(invoke: Invoke) {
        val args = invoke.parseArgs(ScanArgs::class.java)
        if (!ScannerActivity.begin(invoke)) {
            invoke.reject("a scan is open already")
            return
        }
        activity.startActivity(
            Intent(activity, ScannerActivity::class.java)
                .putExtra(ScannerActivity.EXTRA_PROMPT, args.prompt)
                .putExtra(ScannerActivity.EXTRA_CANCEL, args.cancel),
        )
    }
}
